mkuse!{use crate :: marker :: PhantomData ;}
mkuse!{use crate :: num :: NonZero ;}
mkuse!{use crate :: ptr :: NonNull ;}
mkitem!{mkstruct!{# [doc = " A safe iterator over a LPWSTR"] # [doc = " (aka a pointer to a series of UTF-16 code units terminated by a NULL)."] pub struct WStrUnits < 'a > { lpwstr : NonNull < u16 > , lifetime : PhantomData < & 'a [u16] > , }}}
mkitem!{mkimpl!{impl WStrUnits < '_ > { # [doc = " Creates the iterator. Returns `None` if `lpwstr` is null."] # [doc = ""] # [doc = " SAFETY: `lpwstr` must point to a null-terminated wide string that lives"] # [doc = " at least as long as the lifetime of this struct."] pub unsafe fn new (lpwstr : * const u16) -> Option < Self > { Some (Self { lpwstr : NonNull :: new (lpwstr as _) ? , lifetime : PhantomData }) } pub fn peek (& self) -> Option < NonZero < u16 > > { unsafe { NonZero :: new (* self . lpwstr . as_ptr ()) } } # [doc = " Advance the iterator while `predicate` returns true."] # [doc = " Returns the number of items it advanced by."] pub fn advance_while < P : FnMut (NonZero < u16 >) -> bool > (& mut self , mut predicate : P) -> usize { let mut counter = 0 ; while let Some (w) = self . peek () { if ! predicate (w) { break ; } counter += 1 ; self . next () ; } counter } }}}
mkitem!{mkimpl!{impl Iterator for WStrUnits < '_ > { type Item = NonZero < u16 > ; fn next (& mut self) -> Option < Self :: Item > { unsafe { let next = self . peek () ? ; self . lpwstr = NonNull :: new_unchecked (self . lpwstr . as_ptr () . add (1)) ; Some (next) } } }}}